import React from "react";
import { useDocumentState } from "@embedpdf/core/react";

/**
 * A box drawn over a page, e.g. where a metadata value was read from.
 * `page` is 1-based; `box` is [left, top, right, bottom] as fractions (0..1) of the page.
 * `color` is any CSS colour for the outline and label (the fill is a light tint of it); pick a dark
 * one, the label text is white. `active` draws it in the focus colour, on top of the others, and
 * scrolls it into view. `id` names it for the ref API (generated by `highlight.add` when missing).
 */
export interface PDFHighlight {
  id?: string;
  page: number;
  box: [number, number, number, number];
  label?: string;
  color?: string;
  active?: boolean;
}

/** Ref API (`ref.highlight`): boxes added and removed from code, drawn with the `highlights` prop's. */
export interface PDFHighlightAPI {
  /** Adds boxes and returns their ids; a box with an id that is already shown replaces it. */
  add: (highlights: PDFHighlight | PDFHighlight[]) => string[];
  /** Removes the boxes added with these ids. */
  remove: (ids: string | string[]) => void;
  /** Removes every box added through this API and clears the focus. */
  clear: () => void;
  /** Draws the box with this id (from the API or the prop) as active and scrolls to it; null clears. */
  focus: (id: string | null) => void;
  /** The boxes added through this API. */
  list: () => PDFHighlight[];
}

const PAD = 0.004;
const COLORS = {
  normal: { fill: "rgba(255, 213, 0, 0.32)", edge: "rgba(230, 160, 0, 0.95)", text: "#1a1a1a" },
  active: { fill: "rgba(25, 118, 210, 0.22)", edge: "rgba(25, 118, 210, 1)", text: "#ffffff" },
};

/**
 * Highlights for one page. Rendered inside <Rotate>, so it is laid out in unrotated page space
 * and follows zoom and rotation like the other layers. Never takes pointer events.
 */
export function HighlightLayer({
  documentId,
  pageIndex,
  scale,
  highlights,
}: {
  documentId: string;
  pageIndex: number;
  scale: number;
  highlights: PDFHighlight[];
}) {
  const documentState = useDocumentState(documentId);
  const size = documentState?.document?.pages?.[pageIndex]?.size;
  // the active box last, so it is drawn over any box it overlaps
  const mine = highlights
    .filter((h) => h.page === pageIndex + 1)
    .sort((a, b) => Number(!!a.active) - Number(!!b.active));
  if (!size || !mine.length) return null;

  return (
    <div
      style={{
        position: "absolute",
        left: 0,
        top: 0,
        width: size.width * scale,
        height: size.height * scale,
        pointerEvents: "none",
      }}
    >
      {mine.map((h, i) => {
        const [x0, y0, x1, y1] = h.box;
        const c = h.active
          ? COLORS.active
          : h.color
            ? { fill: `color-mix(in srgb, ${h.color} 25%, transparent)`, edge: h.color, text: "#ffffff" }
            : COLORS.normal;
        return (
          <div
            key={h.id ?? i}
            style={{
              position: "absolute",
              left: `${(x0 - PAD) * 100}%`,
              top: `${(y0 - PAD) * 100}%`,
              width: `${(x1 - x0 + 2 * PAD) * 100}%`,
              height: `${(y1 - y0 + 2 * PAD) * 100}%`,
              background: c.fill,
              outline: `2px solid ${c.edge}`,
              borderRadius: 2,
            }}
          >
            {h.label ? (
              <span
                style={{
                  position: "absolute",
                  left: -2,
                  bottom: "100%",
                  marginBottom: 3,
                  padding: "1px 6px",
                  borderRadius: 3,
                  background: c.edge,
                  color: c.text,
                  font: "600 11px/16px system-ui, sans-serif",
                  whiteSpace: "nowrap",
                }}
              >
                {h.label}
              </span>
            ) : null}
          </div>
        );
      })}
    </div>
  );
}
